final class ArchiveTests {
    static void register(DeferredRegister<Consumer<GameTestHelper>> f){
        f.register("archive_scene",()->ArchiveTests::scene);f.register("archive_circuit",()->ArchiveTests::circuit);f.register("archive_echo",()->ArchiveTests::echo);f.register("archive_generation",()->ArchiveTests::generation);f.register("archive_paths",()->ArchiveTests::paths);f.register("archive_route",()->ArchiveTests::route);f.register("archive_restore",()->ArchiveTests::restore);f.register("archive_boss",()->ArchiveTests::boss);f.register("archive_patterns",()->ArchiveTests::patterns);f.register("archive_shortcut",()->ArchiveTests::shortcut);f.register("archive_familiar",()->ArchiveTests::familiar);
        f.register("relic_unlock",()->ArchiveTests::unlock);f.register("relic_authority",()->ArchiveTests::authority);f.register("relic_dodge",()->ArchiveTests::dodge);f.register("relic_guard",()->ArchiveTests::guard);f.register("relic_companion",()->ArchiveTests::companion);f.register("relic_restore",()->ArchiveTests::relicRestore);
    }
    private static void check(GameTestHelper h,boolean value,String m){h.assertTrue(value,Component.literal(m));}
    private static final class Fixture implements AutoCloseable {
        final ServerLevel w;final SanctuaryRoute.Site site;SanctuaryNodeEntity n;final List<BlockPos> platforms=new ArrayList<>();final List<ServerPlayer> players=new ArrayList<>();
        Fixture(GameTestHelper h,int cell,int index){w=FieldworkTests.vestige(h);site=SanctuaryRoute.nearest(cell*6144,cell*6144);var at=SanctuaryRegions.station(site,index);platform(at);w.getChunkAt(at).setData(SanctuaryRegions.GENERATED,true);w.setBlock(at,SanctuaryContent.NODE.get().defaultBlockState(),3);n=(SanctuaryNodeEntity)w.getBlockEntity(at);n.initializeWitness(site,index);for(int i=0;i<index;i++)SanctuaryLedger.get(w.getServer()).finish(site.key(),i);}
        void platform(BlockPos p){FieldworkTests.platform(w,p);platforms.add(p);}
        ServerPlayer player(GameTestHelper h,BlockPos at){var p=FieldworkTests.player(h,w,at);players.add(p);p.addEffect(new net.minecraft.world.effect.MobEffectInstance(net.minecraft.world.effect.MobEffects.RESISTANCE,1600,5));return p;}
        void node(){var at=SanctuaryRegions.station(site,n.index());w.setBlock(at,SanctuaryContent.NODE.get().defaultBlockState(),3);var fresh=(SanctuaryNodeEntity)w.getBlockEntity(at);fresh.initializeWitness(site,n.index());n=fresh;}
        void devices(){for(int i=0;i<3;i++){var at=ArchiveScene.point(n,ArchiveAct.mirror(n.index(),i));platform(at);w.setBlock(at,ArchiveContent.MIRROR.get().defaultBlockState(),3);}}
        public void close(){w.getEntitiesOfClass(SanctuaryConstruct.class,new AABB(n.getBlockPos()).inflate(70)).forEach(Entity::discard);players.forEach(GameplayTests::cleanup);platforms.forEach(p->FieldworkTests.release(w,p));}
    }
    static void scene(GameTestHelper h){var f=new Fixture(h,156,18);var p=f.player(h,f.n.getBlockPos().east(2));f.devices();var obstacle=f.n.local(-18,1,-12);f.w.setBlock(obstacle,Blocks.GOLD_BLOCK.defaultBlockState(),3);var at=ArchiveScene.point(f.n,ArchiveAct.mirror(18,0));p.setPos(Vec3.atBottomCenterOf(at.south(2)));check(h,ArchiveScene.use(f.n,p,at),"The physical mirror turns before a live scene update");h.runAfterDelay(25,()->{try{check(h,f.n.natural()&&f.w.getBlockState(obstacle).is(Blocks.GOLD_BLOCK)&&f.w.getBlockState(at).getValue(ArchiveDeviceBlock.LIT),"Native beam ticks clip safely and retain foreign obstacles and aligned light");h.succeed();}finally{f.close();}});}
    static void circuit(GameTestHelper h){try(var f=new Fixture(h,140,16)){var p=f.player(h,f.n.getBlockPos().east(2));for(int[] d:new int[][]{{-24,8},{24,8},{0,-30}}){var at=f.n.local(d[0],1,d[1]);f.platform(at);p.setPos(Vec3.atBottomCenterOf(at.south(2)));f.n.trace(p,at);}check(h,f.n.traces()==7&&!SanctuaryRoute.done(f.n.mask(),16),"Three stelae cannot bypass the mirror circuit");f.devices();
        var first=ArchiveScene.point(f.n,ArchiveAct.mirror(16,0));p.setPos(Vec3.atBottomCenterOf(first.south(2)));f.w.setBlock(first.south().above(),Blocks.STONE.defaultBlockState(),3);check(h,!ArchiveScene.use(f.n,p,first),"A wall blocks remote mirror operation");f.w.setBlock(first.south().above(),Blocks.AIR.defaultBlockState(),3);
        for(int i=0;i<3;i++){var at=ArchiveScene.point(f.n,ArchiveAct.mirror(16,i));p.setPos(Vec3.atBottomCenterOf(at.south(2)));for(int j=0;j<ArchiveAct.wanted(16,i);j++)check(h,ArchiveScene.use(f.n,p,at),"Each physical click turns exactly one mirror step");}check(h,SanctuaryRoute.done(f.n.mask(),16)&&ArchiveScene.circuit(f.n)==7,"Only the combined objective completes the portico");check(h,!ArchiveScene.use(f.n,p,first),"Completed archive circuits stay latched");}h.succeed();}
    static void echo(GameTestHelper h){try(var f=new Fixture(h,142,21)){var p=f.player(h,f.n.getBlockPos().east(2));int[][] places={{-24,8},{24,8},{0,-30}};
        java.util.function.IntConsumer read=i->{var at=f.n.local(places[i][0],1,places[i][1]);f.platform(at);p.setPos(Vec3.atBottomCenterOf(at.south(2)));f.n.trace(p,at);};
        read.accept(0);check(h,f.n.traces()==0&&!SanctuaryRoute.done(f.n.mask(),21),"An incorrect first memory cannot grant progress");read.accept(2);read.accept(1);check(h,!SanctuaryRoute.done(f.n.mask(),21),"Reading all memories in the wrong order does not finish");read.accept(2);read.accept(0);read.accept(1);check(h,SanctuaryRoute.done(f.n.mask(),21),"Floor-mark order I II III completes the palimpsest");}h.succeed();}
    static void generation(GameTestHelper h){try(var f=new Fixture(h,144,20)){var at=ArchiveScene.point(f.n,ArchiveAct.relay());new SanctuaryFeature().generate(f.w,at);check(h,f.w.getBlockState(at).is(ArchiveContent.RELAY.get())&&!f.w.getBlockState(at.below()).isAir(),"Real chunk generation creates a supported atlas anchor");var upper=f.n.local(38,24,34);new SanctuaryFeature().generate(f.w,upper);check(h,f.w.getBlockState(upper).is(SanctuaryContent.block("obsidian_grate")),"Real worldgen authors the +24 gallery");new SanctuaryFeature().generate(f.w,f.n.getBlockPos());check(h,f.w.getBlockEntity(f.n.getBlockPos()) instanceof SanctuaryNodeEntity n&&n.archive()&&n.natural(),"Only newly authored stations opt in to archive objectives");}h.succeed();}
    static void paths(GameTestHelper h){for(int index=16;index<24;index++){int height=ArchiveAct.height(index);for(int side:new int[]{-1,1})for(int step=0;step<12;step++){int z=-37+step*2,y=step+1;check(h,SanctuaryInterior.sample(side*42,y,z,index,height).is(SanctuaryContent.STAIRS.get())&&SanctuaryInterior.sample(side*42,y+1,z,index,height).isAir()&&SanctuaryInterior.sample(side*42,y+2,z,index,height).isAir(),"Every archive stair has full-body headroom");}}
        for(int j=0;j<4;j++){var p=ArchiveAct.resonance(j);check(h,!SanctuaryInterior.sample(p.x(),p.y()-1,p.z(),20,84).isAir()&&SanctuaryInterior.sample(p.x(),p.y(),p.z(),20,84).isAir()&&SanctuaryInterior.sample(p.x(),p.y()+1,p.z(),20,84).isAir(),"Each atlas resonance has a real floor and headroom");}
        for(int i:new int[]{16,18})for(int j=0;j<3;j++){var p=ArchiveAct.mirror(i,j);for(int y=1;y<=2;y++)check(h,SanctuaryInterior.sample(p.x(),y,p.z()+2,i,ArchiveAct.height(i)).isAir(),"Mirror approach remains clear");}h.succeed();}
    static void route(GameTestHelper h){try(var f=new Fixture(h,146,20)){var p=f.player(h,f.n.getBlockPos().east(2));check(h,f.n.action(p,0),"Atlas traversal starts at its real station");var first=f.n.resonance();f.platform(first);p.setPos(Vec3.atBottomCenterOf(first));f.n.tick();check(h,f.n.sequence()==0,"A dormant anchor does not credit the route");var at=ArchiveScene.point(f.n,ArchiveAct.relay());f.platform(at);f.w.setBlock(at,ArchiveContent.RELAY.get().defaultBlockState(),3);p.setPos(Vec3.atBottomCenterOf(at.south(2)));check(h,ArchiveScene.use(f.n,p,at),"A player without a pet can hold the anchor manually");for(int j=0;j<4;j++){var target=f.n.resonance();f.platform(target);p.setPos(Vec3.atBottomCenterOf(target));f.n.tick();}check(h,SanctuaryRoute.done(f.n.mask(),20)&&f.n.sequence()==4,"Four genuine landings and a live anchor finish the atlas");}h.succeed();}
    static void restore(GameTestHelper h){try(var f=new Fixture(h,148,20)){var tag=f.n.saveWithFullMetadata(f.w.registryAccess());tag.putInt("archiveSpan",6);tag.putInt("archiveHold",1230);tag.putInt("archiveCooling",220);var node=(SanctuaryNodeEntity)BlockEntity.loadStatic(f.n.getBlockPos(),f.n.getBlockState(),tag,f.w.registryAccess());f.n.setRemoved();node.setLevel(f.w);f.w.setBlockEntity(node);f.n=node;var p=f.player(h,node.getBlockPos().east(2));var menu=new SanctuaryMenu(1,p.getInventory(),node);check(h,node.archive()&&menu.value(31)==6&&menu.value(30)==61&&menu.value(32)==11,"Native save and menu preserve archive progress and timers");tag.remove("archiveAct");var old=(SanctuaryNodeEntity)BlockEntity.loadStatic(node.getBlockPos(),node.getBlockState(),tag,f.w.registryAccess());check(h,!old.archive(),"Legacy smelter stations never acquire missing archive machinery");}h.succeed();}
    static void boss(GameTestHelper h){var f=new Fixture(h,150,23);for(int x:new int[]{-16,0,16})for(int z:new int[]{-16,0,16})f.platform(f.n.local(x,1,z));f.node();var p=f.player(h,f.n.getBlockPos().east(2));check(h,f.n.action(p,0),"The Conservator wakes only on deliberate interaction");f.n.tick();
        h.runAfterDelay(3,()->{var all=f.w.getEntitiesOfClass(SanctuaryConstruct.class,new AABB(f.n.getBlockPos()).inflate(65),e->e.kind()==SanctuaryConstruct.Kind.CONSERVATOR);check(h,all.size()==1&&all.getFirst().awakening()>0,"Exactly one owned monumental guardian awakens");var guardian=all.getFirst();var at=f.n.local(0,1,24);f.w.setBlock(at.below(),Blocks.STONE.defaultBlockState(),3);f.w.setBlock(at.above(),Blocks.AIR.defaultBlockState(),3);f.w.setBlock(at.south(2),Blocks.AIR.defaultBlockState(),3);f.w.setBlock(at.south(2).above(),Blocks.AIR.defaultBlockState(),3);f.w.setBlock(at,ArchiveContent.RELAY.get().defaultBlockState(),3);
            h.runAfterDelay(165,()->{try{p.setPos(Vec3.atBottomCenterOf(at.south(2)));check(h,ArchiveScene.use(f.n,p,at)&&guardian.exposed()>100,"A physical arena anchor exposes the real boss");check(h,!ArchiveScene.use(f.n,p,at),"Shared anchor cooldown blocks repeated exposure");guardian.hurtServer(f.w,f.w.damageSources().genericKill(),100000);check(h,SanctuaryRoute.done(f.n.mask(),23)&&p.getInventory().countItem(ArchiveContent.LENS.get())==1&&!f.n.claim(p),"Real defeat grants one personal lens and cannot duplicate it");h.succeed();}finally{f.close();}});
        });}
    static void patterns(GameTestHelper h){var w=h.getLevel();var p=GameplayTests.player(h);var origin=Vec3.atBottomCenterOf(h.absolutePos(new BlockPos(6,4,6)));p.setPos(origin.add(0,0,18));p.setNoGravity(true);var boss=SanctuaryEntities.TYPES.get(SanctuaryConstruct.Kind.CONSERVATOR).get().create(w,EntitySpawnReason.EVENT);boss.setPos(origin);boss.setNoGravity(true);w.addFreshEntity(boss);
        var eraser=SanctuaryEntities.TYPES.get(SanctuaryConstruct.Kind.ARCHIVE_ERASER).get().create(w,EntitySpawnReason.EVENT);eraser.setPos(origin.add(1,0,0));eraser.setNoGravity(true);w.addFreshEntity(eraser);
        h.runAfterDelay(2,()->{try{check(h,boss.beginAttack(p)&&boss.pattern()==7,"The first guardian attack is a real three-opening annulus");check(h,!boss.threatens(origin.add(0,0,5))&&!boss.threatens(p.position())&&boss.threatens(origin.add(18,0,0)),"The annulus has a safe centre and actual angular openings");check(h,eraser.beginAttack(p)&&eraser.pattern()==8,"The archive eraser projects the actual three-lane attack");check(h,eraser.threatens(p.position())&&!eraser.threatens(p.position().add(4,0,0)),"Three marked lanes have walkable gaps");h.succeed();}finally{boss.discard();eraser.discard();GameplayTests.cleanup(p);}});}
    static void shortcut(GameTestHelper h){var f=new Fixture(h,152,20);var p=f.player(h,f.n.getBlockPos().east(2));for(int x=-34;x<=34;x++)for(int z=-26;z<=-22;z++){f.w.getChunkAt(f.n.local(x,24,z));for(int y=24;y<=27;y++)f.w.setBlock(f.n.local(x,y,z),Blocks.AIR.defaultBlockState(),2);}var obstruction=f.n.local(30,24,-24);f.w.setBlock(obstruction,Blocks.GOLD_BLOCK.defaultBlockState(),2);SanctuaryLedger.get(f.w.getServer()).finish(f.site.key(),20);for(int j=0;j<100;j++)f.n.sceneTick();check(h,f.w.getBlockState(obstruction).is(Blocks.GOLD_BLOCK),"Earned bridge animation never overwrites an obstruction");f.w.setBlock(obstruction,Blocks.AIR.defaultBlockState(),2);
        // The scene updates on the world clock, so complete the remaining bounded stages over real ticks.
        h.runAfterDelay(230,()->{try{for(int x=-31;x<=31;x++)check(h,f.w.getBlockState(f.n.local(x,24,-24)).is(SanctuaryContent.block("obsidian_grate")),"Every crossing column is solid after the real staged reconstruction");h.succeed();}finally{f.close();}});}
    static void familiar(GameTestHelper h){var f=new Fixture(h,154,20);var p=f.player(h,f.n.getBlockPos().east(2));var at=ArchiveScene.point(f.n,ArchiveAct.relay());f.platform(at);f.w.setBlock(at,ArchiveContent.RELAY.get().defaultBlockState(),3);p.setPos(Vec3.atBottomCenterOf(at.south(2)));var pet=VestigeEntities.SHARDLING.get().create(f.w,EntitySpawnReason.EVENT);pet.setPos(p.position().add(1,0,0));f.w.addFreshEntity(pet);pet.tame(p);h.runAfterDelay(3,()->{try{check(h,ArchiveScene.use(f.n,p,at)&&pet.archiveHolding(),"The actual owned familiar is assigned the optional relay hold");pet.releaseArchive();check(h,!pet.archiveHolding()&&!pet.isOrderedToSit(),"Releasing the task restores normal following without changing stance");h.succeed();}finally{pet.discard();f.close();}});}
    static void unlock(GameTestHelper h){var p=GameplayTests.player(h);try{p.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,new ItemStack(ArchiveContent.LENS.get()));ArchiveContent.LENS.get().use(p.level(),p,net.minecraft.world.InteractionHand.MAIN_HAND);check(h,p.getData(ArchiveContent.UNLOCKED)&&p.getMainHandItem().isEmpty(),"One lens unlocks the persistent socket and is consumed once");p.closeContainer();}finally{GameplayTests.cleanup(p);}h.succeed();}
    static void authority(GameTestHelper h){var p=GameplayTests.player(h);var stranger=GameplayTests.player(h);try{var menu=new RelicMenu(1,p.getInventory());check(h,!menu.clickMenuButton(p,0)&&!RelicPowers.activate(p),"Locked players cannot select or invoke a relic");p.setData(ArchiveContent.UNLOCKED,true);check(h,!menu.clickMenuButton(stranger,1)&&!menu.clickMenuButton(p,999),"Foreign menu owners and invalid choices are rejected");check(h,menu.clickMenuButton(p,1)&&p.getData(ArchiveContent.SELECTION)==1,"The one socket accepts a validated exclusive choice");}finally{GameplayTests.cleanup(p);GameplayTests.cleanup(stranger);}h.succeed();}
    static void dodge(GameTestHelper h){var p=GameplayTests.player(h);var w=h.getLevel();var start=h.absolutePos(new BlockPos(8,3,8));for(int z=0;z<=6;z++){w.setBlock(start.south(z).below(),Blocks.STONE.defaultBlockState(),2);for(int y=0;y<3;y++)w.setBlock(start.south(z).above(y),Blocks.AIR.defaultBlockState(),2);}p.setPos(Vec3.atBottomCenterOf(start));p.setYRot(0);p.setXRot(0);p.setOnGround(true);p.setData(ArchiveContent.UNLOCKED,true);w.setBlock(start.south(3),Blocks.STONE.defaultBlockState(),2);w.setBlock(start.south(3).above(),Blocks.STONE.defaultBlockState(),2);try{check(h,RelicPowers.activate(p)&&p.getZ()>start.getZ()+1&&p.getZ()<start.getZ()+3,"Dodge advances but stops before a full collision wall");check(h,!RelicPowers.activate(p)&&RelicPowers.remaining(p)==12,"Packet spam cannot bypass the shared dodge cooldown");var menu=new RelicMenu(1,p.getInventory());check(h,!menu.clickMenuButton(p,1),"Changing relic cannot erase an active cooldown");}finally{GameplayTests.cleanup(p);}h.succeed();}
    static void guard(GameTestHelper h){var p=GameplayTests.player(h);try{p.setData(ArchiveContent.UNLOCKED,true);p.setData(ArchiveContent.SELECTION,1);check(h,RelicPowers.activate(p)&&p.hasEffect(net.minecraft.world.effect.MobEffects.ABSORPTION)&&p.getEffect(net.minecraft.world.effect.MobEffects.RESISTANCE).getAmplifier()==1,"Aegis grants precisely the two promised three-second effects");check(h,RelicPowers.remaining(p)==30,"Protection has a real thirty-second shared cooldown");}finally{GameplayTests.cleanup(p);}h.succeed();}
    static void companion(GameTestHelper h){var p=GameplayTests.player(h);var w=h.getLevel();var start=h.absolutePos(new BlockPos(8,3,8));for(int x=-4;x<=4;x++)for(int z=-4;z<=4;z++){w.setBlock(start.offset(x,-1,z),Blocks.STONE.defaultBlockState(),2);for(int y=0;y<=3;y++)w.setBlock(start.offset(x,y,z),Blocks.AIR.defaultBlockState(),2);}p.setPos(Vec3.atBottomCenterOf(start));p.setData(ArchiveContent.UNLOCKED,true);p.setData(ArchiveContent.SELECTION,2);check(h,!RelicPowers.activate(p)&&RelicPowers.remaining(p)==0,"Failed recall without a deployed pet consumes no cooldown");var pet=VestigeEntities.SHARDLING.get().create(w,EntitySpawnReason.EVENT);pet.setPos(p.position().add(4,0,0));w.addFreshEntity(pet);pet.tame(p);h.runAfterDelay(3,()->{try{check(h,RelicPowers.activate(p)&&pet.distanceToSqr(p)<9&&pet.hasEffect(net.minecraft.world.effect.MobEffects.STRENGTH)&&pet.pulseTicks()>0,"Only the owner's real pet recalls safely and receives the animated offensive pulse");h.succeed();}finally{pet.discard();GameplayTests.cleanup(p);}});}
    static void relicRestore(GameTestHelper h){var p=GameplayTests.player(h);try{p.setData(ArchiveContent.UNLOCKED,true);p.setData(ArchiveContent.SELECTION,2);p.setData(ArchiveContent.READY,p.level().getServer().overworld().getGameTime()+400);var out=net.minecraft.world.level.storage.TagValueOutput.createWithContext(net.minecraft.util.ProblemReporter.DISCARDING,p.registryAccess());p.saveWithoutId(out);var tag=out.buildResult();check(h,tag!=null&&tag.toString().contains("archive_relic_selection")&&tag.toString().contains("archive_relic_ready"),"Native player attachment serialization includes the exclusive choice and shared cooldown");var clone=new ServerPlayer(p.level().getServer(),p.level(),p.getGameProfile(),p.clientInformation());clone.load(net.minecraft.world.level.storage.TagValueInput.create(net.minecraft.util.ProblemReporter.DISCARDING,p.registryAccess(),tag));check(h,clone.getData(ArchiveContent.UNLOCKED)&&clone.getData(ArchiveContent.SELECTION)==2&&clone.getData(ArchiveContent.READY).equals(p.getData(ArchiveContent.READY)),"Native player reload retains the unlocked socket, exclusive choice and expiry");var other=GameplayTests.player(h);try{other.restoreFrom(p,false);check(h,other.getData(ArchiveContent.UNLOCKED)&&other.getData(ArchiveContent.SELECTION)==2&&other.getData(ArchiveContent.READY).equals(p.getData(ArchiveContent.READY)),"Death restoration cannot reset the shared cooldown");}finally{GameplayTests.cleanup(other);}var menu=new RelicMenu(1,p.getInventory());check(h,menu.value(0)==1&&menu.value(1)==2&&menu.value(2)==20,"The real menu synchronizes unlock, single socket and countdown");}finally{GameplayTests.cleanup(p);}h.succeed();}
}
